import "./artifact-repository";
import "./config";
import "./network";
import "./database";
import "./compute";
import "./run-reports-job";

// Exposed as a stack output (`pulumi stack output nameServers`) so the registrar delegation for
// each platform domain can be looked up after apply.
export { nameServers } from "./dns";

// The platform VM's static external IP — point DNS A records here as surfaces come online.
export { publicIp } from "./compute";
===COMPUTE===
import * as pulumi from "@pulumi/pulumi";
import * as gcp from "@pulumi/gcp";
import { deployers, location, projectId } from "./config";
import { network, subnet, substrateTag } from "./network";
import { enableService } from "./services";
import { ServiceAccount } from "./service-account";

// Machine type for the substrate VM (Tier B floor). Resize to e2-standard-2 when load requires it —
// a reboot, not a rebuild.
const machineType = new pulumi.Config().get("substrateMachineType") ?? "e2-medium";

const computeApi = enableService("compute.googleapis.com");
const osLoginApi = enableService("oslogin.googleapis.com");
const iapApi = enableService("iap.googleapis.com");

// Identity the substrate VM (and the containers it runs) act as. App-specific grants — Cloud SQL
// client, Secret Manager access — are added in the slices that deploy the apps that need them; this
// covers only what the host itself needs.
const substrateRunner = new ServiceAccount(
  "substrate-runner",
  "Service account for the substrate VM and its containers.",
);

// Host-level observability: let the VM ship logs and metrics to Cloud Monitoring/Logging.
for (const role of ["roles/logging.logWriter", "roles/monitoring.metricWriter"]) {
  new gcp.projects.IAMMember(`substrate-runner-${role.replace("roles/", "")}`, {
    project: projectId,
    role,
    member: substrateRunner.member,
  });
}

// Let deployers reach the VM over IAP-brokered SSH (no public SSH port).
for (const deployer of deployers) {
  for (const role of ["roles/iap.tunnelResourceAccessor", "roles/compute.osLogin"]) {
    new gcp.projects.IAMMember(
      `substrate-ssh-${role.replace("roles/", "")}-${deployer}`,
      {
        project: projectId,
        role,
        member: deployer,
      },
      { dependsOn: iapApi },
    );
  }
}

// Stable external address for the VM, so DNS can point at it and survive VM replacement.
export const address = new gcp.compute.Address("substrate", {
  region: location,
  addressType: "EXTERNAL",
});

// The substrate host: Container-Optimized OS, running the app containers behind Caddy + oauth2-proxy.
// The compose stack (Caddy, oauth2-proxy, and the apps themselves) is deployed in the app slices;
// this stands up a ready container host. DNS A records are added when a surface actually serves.
export const instance = new gcp.compute.Instance(
  "substrate",
  {
    machineType,
    zone: `${location}-a`,
    tags: [substrateTag],
    bootDisk: {
      initializeParams: {
        image: "cos-cloud/cos-stable",
        size: 30,
        type: "pd-balanced",
      },
    },
    networkInterfaces: [
      {
        subnetwork: subnet.id,
        accessConfigs: [{ natIp: address.address }],
      },
    ],
    serviceAccount: {
      email: substrateRunner.email,
      scopes: ["cloud-platform"],
    },
    // OS Login ties SSH access to IAM (the grants above) instead of managing keys by hand.
    metadata: { "enable-oslogin": "TRUE" },
    // Allow machine-type resize (e2-medium -> e2-standard-2) without recreating the VM.
    allowStoppingForUpdate: true,
  },
  { dependsOn: [network, computeApi, osLoginApi] },
);

export const publicIp = address.address;
===NETWORK===
import * as gcp from "@pulumi/gcp";
import { location } from "./config";
import { enableService } from "./services";

const computeApi = enableService("compute.googleapis.com");
const servicenetworkingApi = enableService("servicenetworking.googleapis.com");

// Tag applied to the substrate VM; the firewall rules below target it.
export const substrateTag = "substrate";

// Private VPC for the substrate. Cloud SQL and the VM communicate over private IP; the VM's only
// public exposure is HTTPS via the firewall rule below.
export const network = new gcp.compute.Network(
  "substrate",
  { autoCreateSubnetworks: false },
  { dependsOn: computeApi },
);

// Regional subnet the substrate VM lives in. Private Google access lets it reach Google APIs
// without a public route.
export const subnet = new gcp.compute.Subnetwork("substrate", {
  network: network.id,
  region: location,
  ipCidrRange: "10.0.0.0/24",
  privateIpGoogleAccess: true,
});

// Caddy terminates TLS for every surface, so open 443 (and 80 for ACME/HTTP->HTTPS) to the world.
new gcp.compute.Firewall("allow-https", {
  network: network.id,
  allows: [{ protocol: "tcp", ports: ["80", "443"] }],
  sourceRanges: ["0.0.0.0/0"],
  targetTags: [substrateTag],
});

// SSH only from Google's IAP TCP-forwarding range — no world-facing SSH port. The database is never
// exposed: it's reachable only over the private services peering, so no rule opens its port.
new gcp.compute.Firewall("allow-ssh-iap", {
  network: network.id,
  allows: [{ protocol: "tcp", ports: ["22"] }],
  sourceRanges: ["35.235.240.0/20"],
  targetTags: [substrateTag],
});

// Reserve an internal range and peer it with Google's service networking, so Cloud SQL can be
// assigned a private IP inside our VPC.
const privateRange = new gcp.compute.GlobalAddress("private-services", {
  purpose: "VPC_PEERING",
  addressType: "INTERNAL",
  prefixLength: 16,
  network: network.id,
});

export const privateServicesConnection = new gcp.servicenetworking.Connection(
  "private-services",
  {
    network: network.id,
    service: "servicenetworking.googleapis.com",
    reservedPeeringRanges: [privateRange.name],
  },
  { dependsOn: servicenetworkingApi },
);

